function delete_button(string $action,int $id): void { ?><form method="post" data-confirm="Padam rekod ini? Rekod yang masih mempunyai lantikan perlu dilepaskan dahulu."><?= csrf() ?><input type="hidden" name="action" value="<?= $action ?>"><input type="hidden" name="id" value="<?= $id ?>"><button class="delete-btn">Padam</button></form><?php }
function teacher_table(array $rows,bool $actions): void { ?><div class="table-wrap"><table id="teacher-table"><thead><tr><th>Guru</th><th>Bil. tugas</th><th>Beban / kapasiti</th><th>Status</th><?php if($actions): ?><th>Tindakan</th><?php endif ?></tr></thead><tbody><?php foreach($rows as $t): ?><tr><td><div class="student-cell"><span class="avatar small"><?= e(mb_substr($t['name'],0,1)) ?></span><div><strong><?= e($t['name']) ?></strong><small><?= e($t['specialty']) ?></small></div></div></td><td><?= $t['task_count'] ?> tugas</td><td><div class="load-cell"><span><strong><?= $t['load'] ?></strong> / <?= $t['capacity'] ?> mata</span><progress class="<?= $t['load']>$t['capacity']?'over':'' ?>" value="<?= min($t['load'],$t['capacity']) ?>" max="<?= $t['capacity'] ?>"></progress></div></td><td><?= badge($t) ?></td><?php if($actions): ?><td><div class="row-actions"><a class="text-link" href="/?page=teachers&edit=<?= $t['id'] ?>#editor">Sunting</a><?php delete_button('delete_teacher',$t['id']); ?></div></td><?php endif ?></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty">Tiada guru dalam senarai ini.</p><?php endif ?><p class="search-empty" hidden>Tiada guru sepadan.</p></div><?php }
